/**
 * January rhythm-skeleton cron (task 3.1, change calendar-event-automation;
 * spec "Automatic rhythm-skeleton generation") — once a year, on
 * 1 January 00:00 UTC, the year's two ALKO_PRICE_LIST EXPECTED rows are
 * generated by the pure core-domain generator
 * ({@link generateAlkoSkeleton}) and inserted into `calendar_events`.
 *
 * ## The clock — one read, the cron context
 *
 * The target year is the CURRENT year at tick time: the pattern fires at
 * 00:00 UTC on 1 January, so the current year IS the new year the
 * skeleton belongs to (design D — Helsinki is 02:00 local, harmless;
 * wrangler crons are UTC-only, see the wrangler.jsonc timezone note).
 * `new Date()` here is the one legitimate clock read — a cron tick is
 * the schedule's own context, and no other module in the path reads a
 * clock (the generator is pure).
 *
 * ## Idempotency — ignore-if-present through the generator's year rule
 *
 * The coverage input is the year's existing rows read through the SAME
 * DrizzleCalendarEventRepository the public calendar API serves from
 * (the fan-out twin's year read). The generator's all-or-nothing year
 * rule is the single gate: ANY ALKO_PRICE_LIST row already in the year —
 * seed, ops console, or a previous tick — and the whole year is skipped,
 * so at-least-once delivery can never duplicate rows (a re-run after a
 * crash re-enters the same skip). Non-Alko rows in the year (the FI
 * excise change, …) never block generation.
 *
 * ## Insertion — the console-parity insert
 *
 * Rows go in through the persistence-boundary validator and the ops
 * calendar-events console-parity insert (MAX(id)+1, the sibling fan-out's
 * convention): the single-operator calendar has no allocation race to
 * defend against, and the validator keeps exactly one content contract —
 * a generated row that failed validation would land in this module's
 * fail-open log, never in the table.
 *
 * @module CalendarSkeletonCron
 */

import { generateAlkoSkeleton } from '../../../../packages/core-domain/src/calendar/calendar.skeleton';
import type { CalendarSkeletonCoverageEvent } from '../../../../packages/core-domain/src/calendar/calendar.skeleton';
import {
  validateCalendarEvent,
  type ValidatedCalendarEvent,
} from '../../../../packages/data-platform/src/repositories/calendar-event-validator';
import { DrizzleCalendarEventRepository } from '../../../../packages/data-platform/src/repositories/calendar-event.repository';
import type { Env } from '../env';
import type { Logger } from '../logger';

/** The annual pattern: 00:00 UTC every 1 January (see module docstring). */
export const CALENDAR_SKELETON_CRON = '0 0 1 1 *';

/** One skeleton run's outcome — logged by the wrapper, asserted by tests. */
export interface CalendarSkeletonRunResult {
  /** The year the run covered (the current year at tick time). */
  readonly year: number;
  /** Rows actually inserted (0 when the year was already covered). */
  readonly inserted: number;
  /**
   * inserted — the skeleton rows went in; year-covered — the year
   * already carries an Alko row, the generator emitted nothing.
   */
  readonly outcome: 'inserted' | 'year-covered';
}

/**
 * The console-parity insert (the sibling fan-out's convention): id
 * beyond every existing row (MAX(id)+1 — single-operator calendar, no
 * allocation race). Returns the assigned id.
 */
async function insertCalendarEventRow(
  env: Env,
  event: ValidatedCalendarEvent,
): Promise<number> {
  const head = await env.DB.prepare(
    'SELECT MAX(id) AS max_id FROM calendar_events',
  ).first<{ max_id: number | null }>();
  const id = (head?.max_id ?? 0) + 1;
  await env.DB.prepare(
    'INSERT INTO calendar_events ' +
      '(id, year, event_type, status, occurrence_date, expected_window, ' +
      'title_fi, title_en, summary_fi, summary_en, source_url) ' +
      'VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
  )
    .bind(
      id,
      event.year,
      event.eventType,
      event.status,
      event.occurrenceDate,
      event.expectedWindow,
      event.titleFi,
      event.titleEn,
      event.summaryFi,
      event.summaryEn,
      event.sourceUrl,
    )
    .run();
  return id;
}

/**
 * One January-tick run: read the year's existing rows through the
 * calendar repository, let the pure generator decide (all-or-nothing
 * year rule), validate and insert what it emits. Throws on failure —
 * the fail-open wrapper below is the entry the router registers, never
 * this function.
 *
 * `deps` is a test seam (year, coverage read, insert), the same pattern
 * the sibling cron handlers use.
 */
export async function handleCalendarSkeleton(
  env: Env,
  log: Logger,
  deps: {
    /** Target-year seam (tests) — defaults to the current UTC year. */
    year?: number;
    /** Coverage read seam (tests) — defaults to the calendar repository. */
    listEvents?: (
      year: number,
    ) => Promise<readonly CalendarSkeletonCoverageEvent[]>;
    /** Insert seam (tests) — returns the assigned row id. */
    insertEvent?: (event: ValidatedCalendarEvent) => Promise<number>;
  } = {},
): Promise<CalendarSkeletonRunResult> {
  // The one clock read: the cron tick is the schedule's own context.
  const year = deps.year ?? new Date().getUTCFullYear();

  // Coverage input = the year's (year, event_type) rows through the SAME
  // repository the public calendar API serves; the generator reads only
  // those two fields.
  const existing = deps.listEvents
    ? await deps.listEvents(year)
    : await new DrizzleCalendarEventRepository(env.DB).listByYear(year);
  const skeleton = generateAlkoSkeleton(
    year,
    existing.map((event) => ({ year: event.year, eventType: event.eventType })),
  );

  if (skeleton.length === 0) {
    log.info({
      message: `Calendar skeleton skipped: ${year} already carries an ALKO_PRICE_LIST event (idempotent year rule)`,
      year,
      inserted: 0,
    });
    return { year, inserted: 0, outcome: 'year-covered' };
  }

  let inserted = 0;
  for (const row of skeleton) {
    // The persistence-boundary validator is the single content contract;
    // a generated row is a constant-shaped EXPECTED row and always
    // passes — but the boundary stays the boundary.
    const validated = validateCalendarEvent(row);
    const id = deps.insertEvent
      ? await deps.insertEvent(validated)
      : await insertCalendarEventRow(env, validated);
    inserted += 1;
    log.info({
      message: `Calendar skeleton row inserted for ${year} (${validated.expectedWindow})`,
      year,
      eventId: id,
      expectedWindow: validated.expectedWindow,
    });
  }

  log.info({
    message: `Calendar skeleton complete: ${inserted} ALKO_PRICE_LIST rows for ${year}`,
    year,
    inserted,
  });
  return { year, inserted, outcome: 'inserted' };
}

/**
 * The fail-open wrapper — the entry the router registers. Never throws:
 * every failure is caught and logged, and the wrapper resolves to null
 * (the fan-out twin's wrapper; the scheduled invocation completes —
 * per-handler isolation in the router stays the second belt).
 */
export async function runCalendarSkeleton(
  env: Env,
  log: Logger,
): Promise<CalendarSkeletonRunResult | null> {
  try {
    return await handleCalendarSkeleton(env, log);
  } catch (err) {
    log.error({
      message: `Calendar skeleton failed (fail-open, the tick completes): ${
        err instanceof Error ? err.message : 'unknown error'
      }`,
    });
    return null;
  }
}
